namespace ghidra.app.util.viewer.field;





using docking.widgets.fieldpanel.field;
using ghidra.app.nav;
using ghidra.app.services;
using ghidra.app.util;
using ghidra.app.util.query;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.symbol;
using ghidra.program.util;

/**
 * A handler to process XRef field clicks
 */
public class XRefFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES =
		new Class<object>[] { typeof(XRefFieldLocation), typeof(XRefHeaderFieldLocation) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable sourceNavigatable,
			ProgramLocation location, MouseEvent mouseEvent, ServiceProvider serviceProvider) {

		if (mouseEvent.getClickCount() != 2 || mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}

		GoToService goToService = serviceProvider.getService(typeof(GoToService));
		if (goToService == null) {
			return false;
		}

		// If I double-click on the XRef Header, show references to this place, also works on
		// 'more' field. This is much nicer if you have multiple references to navigate.
		if (isXREFHeaderLocation(location)) {
			showXRefDialog(sourceNavigatable, location, serviceProvider);
			return true;
		}

		Address referencedAddress = getFromReferenceAddress(location);
		bool isInvisibleXRef = isInvisibleXRef(clickedObject);
		if (isInvisibleXRef) {
			showXRefDialog(sourceNavigatable, location, serviceProvider);
			return true;
		}

		return goTo(sourceNavigatable, referencedAddress, goToService);
	}

	private bool isInvisibleXRef(object clickedObject) {

		string clickedText = getText(clickedObject);
		if (XRefFieldFactory.MORE_XREFS_STRING.equals(clickedText)) {
			return true;
		}

		if (clickedObject is StrutFieldElement) {
			// this implies that the xrefs field has been clipped and has used a struct to trigger
			// clipping
			return true;
		}
		return false;
	}

	protected bool isXREFHeaderLocation(ProgramLocation location) {
		return location is XRefHeaderFieldLocation;
	}

	private string getText(object clickedObject) {
		if (clickedObject is TextField) {
			TextField textField = (TextField) clickedObject;
			return textField.getText();
		}
		else if (clickedObject is FieldElement) {
			FieldElement fieldElement = (FieldElement) clickedObject;
			return fieldElement.getText();
		}
		return clickedObject.toString();
	}

	protected Address getFromReferenceAddress(ProgramLocation programLocation) {
		return programLocation.getRefAddress();
	}

	protected void showXRefDialog(Navigatable navigatable, ProgramLocation location,
			ServiceProvider serviceProvider) {
		TableService service = serviceProvider.getService(typeof(TableService));
		if (service == null) {
			return;
		}

		Supplier<Collection<Reference>> refs = () => XReferenceUtils.getAllXrefs(location);
		XReferenceUtils.showXrefs(navigatable, serviceProvider, service, location, refs);
	}

	private bool goTo(Navigatable navigatable, Address referencedAddress,
			GoToService goToService) {
		if (referencedAddress != null) {
			return goToService.goTo(navigatable, referencedAddress);
		}
		return false;
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}
}
